        [GL.LINES]: "line-list",
        [GL.LINE_STRIP]: "line-strip",
        [GL.LINE_LOOP]: "line-strip",
        [GL.TRIANGLES]: "triangle-list",
        [GL.TRIANGLE_STRIP]: "triangle-strip",
        [GL.TRIANGLE_FAN]: "triangle-list",
        [GL.QUADS]: "triangle-list",
        [GL.QUAD_STRIP]: "triangle-list",
