        DCL_UAV_STRUCTURED: 158, DCL_TGSM_RAW: 159, DCL_TGSM_STRUCTURED: 160, DCL_RESOURCE_RAW: 161,
        DCL_RESOURCE_STRUCTURED: 162, LD_UAV_TYPED: 163, STORE_UAV_TYPED: 164, LD_RAW: 165, STORE_RAW: 166,
